"use client";
import { useState } from "react";
import Link from "next/link";
import {
  messageBlocks,
  messageInline,
  type MessageText,
} from "@/lib/message-format";
import {
  PreviewHighlightPicker,
  usePreviewHighlight,
} from "./preview-highlight";
import { Check, AlertTriangle } from "lucide-react";
export type PreviewContact = {
  id: string;
  name: string;
  email: string;
  company: string | null;
  jobRole: string | null;
};
export type PreviewPart = { text: string; kind: "text" | "filled" | "invalid" };
export function previewParts(
  text: string,
  values: Record<string, string | null>,
) {
  const parts: PreviewPart[] = [];
  const errors: string[] = [];
  const tokens = /{{([\s\S]*?)}}|{{[^{}]*|}}/g;
  let cursor = 0;
  for (const match of text.matchAll(tokens)) {
    if (match.index > cursor)
      parts.push({ text: text.slice(cursor, match.index), kind: "text" });
    const token = match[1]?.trim();
    const valid =
      token !== undefined &&
      ["name", "company", "role"].includes(token) &&
      Object.hasOwn(values, token);
    parts.push({
      text: valid ? (values[token!] ?? "") : match[0],
      kind: valid ? "filled" : "invalid",
    });
    if (!valid)
      errors.push(
        token === undefined || token.includes("{{")
          ? "A {{ }} bracket is not closed."
          : token === "link"
            ? "Replace {{link}} with a URL directly in your message."
            : `Unknown placeholder: ${match[0]}.`,
      );
    cursor = match.index + match[0].length;
  }
  if (cursor < text.length)
    parts.push({ text: text.slice(cursor), kind: "text" });
  return { parts, errors };
}
export function Highlighted({ parts }: { parts: PreviewPart[] }) {
  return parts.map((part, i) =>
    part.kind === "text" ? (
      <span key={i}>{part.text}</span>
    ) : (
      <mark key={i} className={part.kind === "invalid" ? "invalid" : undefined}>
        {part.text}
      </mark>
    ),
  );
}
export function FormattedMessage({ parts }: { parts: PreviewPart[] }) {
  const text = parts.map((part) => part.text).join("");
  function inline(content: MessageText) {
    return messageInline(content).map((fragment, index) => {
      let cursor = 0;
      const highlighted = parts.flatMap((part) => {
        const start = Math.max(fragment.start, cursor);
        const end = Math.min(
          fragment.start + fragment.text.length,
          cursor + part.text.length,
        );
        const slice =
          start < end
            ? [{ ...part, text: part.text.slice(start - cursor, end - cursor) }]
            : [];
        cursor += part.text.length;
        return slice;
      });
      return fragment.bold ? (
        <strong key={index}>
          <Highlighted parts={highlighted} />
        </strong>
      ) : (
        <Highlighted key={index} parts={highlighted} />
      );
    });
  }
  return messageBlocks(text).map((block, index) => {
    if (block.kind === "text") return <span key={index}>{inline(block)}</span>;
    const items = block.items.map((item, i) => <li key={i}>{inline(item)}</li>);
    return block.kind === "ul" ? (
      <ul key={index}>{items}</ul>
    ) : (
      <ol key={index} start={block.number}>
        {items}
      </ol>
    );
  });
}
export function TemplatePreview({
  contacts,
  subject,
  body,
}: {
  contacts: PreviewContact[];
  subject: string;
  body: string;
}) {
  const highlight = usePreviewHighlight();
  const [recipientId, setRecipientId] = useState(contacts[0]?.id ?? "");
  const recipient =
    contacts.find((contact) => contact.id === recipientId) ?? contacts[0];
  const values = recipient
    ? {
        name: recipient.name,
        company: recipient.company,
        role: recipient.jobRole,
      }
    : {
        name: "Recipient name",
        company: "Company",
        role: "Job role",
      };
  const renderedSubject = previewParts(subject, values);
  const renderedBody = previewParts(body, values);
  const errors = [
    ...new Set([...renderedSubject.errors, ...renderedBody.errors]),
  ];
  const missing = [
    ...new Set(
      [
        ...subject.matchAll(/{{\s*(name|company|role)\s*}}/g),
        ...body.matchAll(/{{\s*(name|company|role)\s*}}/g),
      ]
        .filter((match) => !values[match[1] as keyof typeof values])
        .map((match) => match[1]),
    ),
  ];
  return (
    <aside
      className="panel template-editor-preview min-w-0 flex flex-col gap-3.5 p-5.5 [background:var(--card)] [border:1px_solid_var(--border)] sticky top-4 h-[calc(100dvh_-_140px)] [@media(max-width:_959px)]:p-4 [@media(max-width:_959px)]:static [@media(max-width:_959px)]:h-[70dvh] [@media(max-width:_959px)]:min-h-115"
      aria-label="Live email preview"
    >
      <div className="template-editor-preview-header flex flex-wrap items-center gap-3">
        <h2 className="section-label [font:600_11px/1.5_ui-monospace,_monospace] tracking-[0.14em] uppercase text-body">
          Live preview
        </h2>
        <span className="ml-auto flex items-center gap-1.5 font-mono text-xs font-bold text-success">
          <span
            className="live-dot size-2 rounded-full bg-current"
            aria-hidden="true"
          />
          LIVE
        </span>
        <label className="sr-only" htmlFor="template-preview-as">
          Preview as
        </label>
        <div className="preview-recipient-controls flex-[1_1_100%] min-w-0 flex items-center gap-2">
          <select
            id="template-preview-as"
            className="w-full flex-1 min-w-0 text-ellipsis"
            value={recipient?.id ?? ""}
            disabled={!contacts.length}
            onChange={(event) => setRecipientId(event.target.value)}
          >
            {contacts.length ? (
              contacts.map((contact) => (
                <option key={contact.id} value={contact.id}>
                  {[contact.name, contact.company, contact.jobRole]
                    .filter(Boolean)
                    .join(" · ")}
                </option>
              ))
            ) : (
              <option value="">Sample recipient — no saved contacts</option>
            )}
          </select>
          <PreviewHighlightPicker />
        </div>
      </div>
      {!contacts.length && (
        <p className="text-xs text-body">
          Sample values shown.{" "}
          <Link className="text-link" href="/contacts">
            Add a contact
          </Link>{" "}
          to preview a real recipient.
        </p>
      )}
      <div
        className="mail-preview min-w-0 flex flex-col flex-1 min-h-0 overflow-hidden [background:var(--surface)] [border:1px_solid_var(--border)] rounded-[16px] wrap-anywhere"
        data-preview-highlight={highlight}
      >
        <div className="shrink-0 border-b border-dotted border-separator px-4 py-3">
          <p className="text-xs text-body">
            To: {recipient?.email ?? "Sample recipient"}
          </p>
          <p className="mt-1 font-semibold">
            <Highlighted parts={renderedSubject.parts} />
          </p>
        </div>
        <div
          className="mail-preview-body flex-1 min-h-0 max-h-none overflow-y-auto whitespace-pre-wrap wrap-anywhere focus-visible:[outline:2px_solid_var(--accent)] focus-visible:[outline-offset:-2px] p-4"
          role="region"
          aria-label="Template message preview"
          tabIndex={0}
        >
          <div className="mail-message-content w-full max-w-160 [font-family:Arial,_Helvetica,_sans-serif] text-[14px] leading-normal text-left">
            <FormattedMessage parts={renderedBody.parts} />
          </div>
        </div>
      </div>
      <p
        role="status"
        className={`shrink-0 flex items-start gap-1.5 text-xs ${errors.length ? "text-error-deep" : missing.length ? "text-warning" : "text-success"}`}
      >
        {errors.length || missing.length ? (
          <AlertTriangle className="size-4 shrink-0" aria-hidden="true" />
        ) : (
          <Check className="size-4 shrink-0" aria-hidden="true" />
        )}
        <span>
          {errors.length
            ? errors.join(" ")
            : missing.length
              ? `Missing values: ${missing.join(", ")}. These placeholders resolve to empty text.`
              : "Looks good. Highlighted text is filled in per recipient."}
        </span>
      </p>
    </aside>
  );
}
